const NCM_ITEMS = NCM_RAW.i.map(([code, hIdx, desc]) => {
  const heading = NCM_RAW.h[hIdx] || "";
  const formatted = `${code.slice(0, 4)}.${code.slice(4, 6)}.${code.slice(6, 8)}`;
  const tax = NCM_TAX_RAW[code];
  const aliquotaII = tax ? tax[0] / 100 : null;
  const aliquotaIPI = tax ? tax[1] / 100 : null;
  const exTarifario = !!(tax && tax[2] === 1);
  return {
    code, formatted, heading, desc, aliquotaII, aliquotaIPI, exTarifario,
    search: stripAccents(`${formatted} ${code} ${heading} ${desc}`),
  };
});

// ---------------------------------------------------------------------------
// ICMS interno por estado — Fonte: Focus NFe, "Tabela ICMS 2026: alíquotas
// internas e interestaduais atualizadas", publicado 04/08/2026, consultado em
// 25/08/2026. FCP = adicional do Fundo de Combate à Pobreza quando existente.
// Confirme sempre na SEFAZ do estado de destino antes de uma operação real —
// alíquotas mudam por lei estadual e podem variar por mercadoria (ex.: SC tem
// alíquota reduzida de 12% para uma lista de itens).
// ---------------------------------------------------------------------------
const ICMS_FONTE = "Focus NFe — Tabela ICMS 2026 (publ. 04/08/2026, consultado 25/08/2026)";
const TEC_TIPI_FONTE = "TEC/TIPI (Receita Federal/Siscomex) — pasta \"Documentos - impostos\" enviada pelo usuário";

// ---------------------------------------------------------------------------
// Core calculation engine
// Implements the flow: Preço + Frete + Seguro = Valor Aduaneiro
// Valor Aduaneiro + tributos + despesas = Custo Total da Importação
// Custo Total / Quantidade = Custo Unitário
// ---------------------------------------------------------------------------
function computeImport(p, { qty, precoUnitario, baseQuantidade } = {}) {
  const q = qty ?? p.quantidade;
  const preco = precoUnitario ?? p.precoUnitario;
  const base = baseQuantidade ?? p.quantidade;
  const scale = base > 0 ? q / base : 1;

  const cambio = p.cotacao;
  const valorProdutoOrigem = preco * q; // sempre em USD
  const freteInternoOrigem = p.incoterm === "EXW" ? p.freteInternoChina : 0;
  const freteIntlOrigem = p.freteInternacional * scale;
  const seguroOrigem = p.seguroInternacional * scale;

  let valorAduaneiroOrigem;
  if (p.incoterm === "CIF") {
    valorAduaneiroOrigem = valorProdutoOrigem;
  } else if (p.incoterm === "FOB") {
    valorAduaneiroOrigem = valorProdutoOrigem + freteIntlOrigem + seguroOrigem;
  } else {
    valorAduaneiroOrigem = valorProdutoOrigem + freteInternoOrigem + freteIntlOrigem + seguroOrigem;
  }

  const valorAduaneiro = valorAduaneiroOrigem * cambio; // BRL
  const freteIntlBRL = freteIntlOrigem * cambio;

  const II = valorAduaneiro * p.aliquotaII;
  const IPI = (valorAduaneiro + II) * p.aliquotaIPI;
  const PIS = valorAduaneiro * p.aliquotaPIS;
  const COFINS = valorAduaneiro * p.aliquotaCOFINS;
  const AFRMM = p.modal === "maritimo" ? freteIntlBRL * p.afrmmAliquota : 0;
  const taxaSiscomex = p.taxaSiscomex;

  const despesasAduaneiras = p.despachante + p.armazenagem + p.despesasPortuarias + p.outrasDespesas;
  const despesasLogisticas = p.transportePortoEstoque + p.agenteCarga;

  const somaAntesICMS = valorAduaneiro + II + IPI + PIS + COFINS + AFRMM + taxaSiscomex + despesasAduaneiras;
  const denom = 1 - p.aliquotaICMS;
  const baseICMS = denom > 0 ? somaAntesICMS / denom : somaAntesICMS;
  const ICMS = baseICMS * p.aliquotaICMS;

  const custoTotal = valorAduaneiro + II + IPI + PIS + COFINS + AFRMM + taxaSiscomex + ICMS + despesasAduaneiras + despesasLogisticas;
  const custoUnitario = q > 0 ? custoTotal / q : 0;

  const creditos =
    (p.creditoICMS ? ICMS : 0) +
    (p.creditoPIS ? PIS : 0) +
    (p.creditoCOFINS ? COFINS : 0) +
    (p.creditoIPI ? IPI : 0);
  const custoLiquido = custoTotal - creditos;
  const custoUnitarioLiquido = q > 0 ? custoLiquido / q : 0;

  return {
    q, preco, valorProdutoOrigem, freteInternoOrigem, freteIntlOrigem, seguroOrigem,
    valorAduaneiro, II, IPI, PIS, COFINS, AFRMM, taxaSiscomex,
    despesasAduaneiras, despesasLogisticas, ICMS, baseICMS,
    custoTotal, custoUnitario, creditos, custoLiquido, custoUnitarioLiquido,
  };
}

