  ncmObs: "NCM hipotético — confirmar classificação fiscal antes de uma importação real",
  cest: "",
  quantidade: 20,
  precoUnitario: 200,
  cotacao: 5.40,
  incoterm: "FOB",
  freteInternoChina: 0,
  freteInternacional: 1200,
  seguroInternacional: 100,
  modal: "maritimo",
  portoEntrada: "Santos/SP",
  estadoDestino: "SP",
  despesasPortuarias: 800,
  afrmmAliquota: 0.25,
  taxaSiscomex: 154.23,
  despachante: 600,
  agenteCarga: 300,
  armazenagem: 500,
  transportePortoEstoque: 400,
  outrasDespesas: 0,
  regimeTributario: "Lucro Presumido",
  aliquotaII: 0.16,
  aliquotaIPI: 0.10,
  aliquotaPIS: 0.021,
  aliquotaCOFINS: 0.0964,
  aliquotaICMS: 0.18,
  fcpICMS: null,
  creditoICMS: true,
  creditoPIS: true,
  creditoCOFINS: true,
  creditoIPI: false,
  fonteII: "",
  fonteIPI: "",
  fontePISCOFINS: "",
  fonteICMS: ICMS_FONTE,
